"""Build the offline Nocturne color study; does not modify the application."""
from pathlib import Path
import ast, json
OUT=Path(__file__).resolve().parent
# Reuse the previous artbook's small vector icon set, without executing its build.
source=ast.parse((OUT.parent/'artbook-2026-10/build.py').read_text())
icons=next(ast.literal_eval(n.value) for n in source.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='paths' for t in n.targets))
icons.update({'down':'M5 9l7 7 7-7','calendar':'M4 5h16v16H4z M4 10h16 M8 2v6 M16 2v6','headphones':'M4 13v-2a8 8 0 0 1 16 0v2 M4 12h4v9H4z M16 12h4v9h-4z','smile':'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M8 9h.1 M16 9h.1 M7 14q5 6 10 0','refresh':'M20 8a9 9 0 1 0 1 8 M20 3v6h-6'})
# id, title, mood, background, surface, raised, accent, on accent, muted, secondary
THEMES=[('cloud', '11 / Lavender Cloud', 'Лавандовое облако · мягкий сиреневый', '#f5f2fb', '#ffffff', '#eae3f5', '#66508c', '#30263e', '#655c73', '#80556b', '#dcd0ef', '#302a3a'), ('mint', '12 / Mint Tea', 'Мятный чай · прохлада и спокойствие', '#f0f7f3', '#fcfffd', '#dfede4', '#38644d', '#233e2c', '#52685b', '#775e45', '#c8e5d4', '#293b30'), ('peach', '13 / Peach Milk', 'Персиковое молоко · тёплая нежность', '#fff5ee', '#fffdfb', '#f7e4d7', '#89543c', '#4b3024', '#775e50', '#6e6088', '#f3d1b9', '#433127'), ('sky', '14 / Sky Linen', 'Небесный лён · воздушный голубой', '#f1f6fb', '#ffffff', '#e0eaf5', '#3f6186', '#263a51', '#566a7f', '#79596e', '#cadff1', '#293747'), ('rose', '15 / Rosewater', 'Розовая вода · пудровый румянец', '#fcf2f5', '#fffcfd', '#f2e0e7', '#8a5069', '#4c2c3a', '#795d69', '#516357', '#edccd9', '#433039'), ('vanilla', '16 / Vanilla', 'Ванильный крем · мягкий солнечный свет', '#fbf8ed', '#fffef8', '#f1ead6', '#796130', '#42351c', '#6e6550', '#6a557c', '#eadeb4', '#3d3729'), ('lilac', '17 / Wisteria', 'Глициния · прохладный сине-сиреневый', '#f0f2fc', '#fcfdff', '#e0e5f6', '#53638c', '#29354a', '#59637b', '#755539', '#cbd5f2', '#2c3547'), ('aqua', '18 / Seafoam', 'Морская пена · светлая бирюза', '#edf8f7', '#fbfffe', '#dcefed', '#336862', '#213d3a', '#506c67', '#78514c', '#bfe3dd', '#283e3b'), ('sage', '19 / Pistachio', 'Фисташка · нежный природный тон', '#f4f6ed', '#fefff9', '#e7ecd9', '#586b3c', '#303b21', '#606b51', '#78503f', '#d9e4c1', '#343d2b'), ('oat', '20 / Oat Silk', 'Овсяный шёлк · тёплый нейтральный', '#f7f4ef', '#fffefa', '#eae4da', '#71614f', '#3d3329', '#6b6358', '#605976', '#dfd4c3', '#3b352e')]
def icon(n):return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{icons[n]}"/></svg>'
def ib(n,cls=''):return f'<span class="iconbox {cls}">{icon(n)}</span>'
def av(name,cls=''):return f'<span class="avatar {cls}">{name}</span>'
def wave():return '<div class="wave" aria-hidden="true">'+''.join(f'<i style="height:{h}px"></i>' for h in [10,18,28,15,22,37,31,19,12,24,34,20,10,17,29,38,23,15,28,35,18,10,21,27,14,8,20,30])+'</div>'
def tag(s,cls=''):return f'<span class="tag {cls}">{s}</span>'
def top(t,s=''):return f'<div class="top">{ib("back")}<div><b>{t}</b><small>{s}</small></div>{ib("more")}</div>'
def hero(k,t):return f'<div class="screenhero"><small>{k}</small><h3>{t}</h3></div>'
def voice(own=False):return f'<div class="voice {"ownvoice" if own else ""}"><div class="vlabel"><b>Голосовое сообщение</b><span>0:18</span></div><div class="vplay">{ib("play","accent")}{wave()}</div><div class="stamp">14:32</div></div>'
def message(text,own=False,time='14:30'):return f'<div class="bubble {"own" if own else ""}">{text}<small>{time}{" · прочитано" if own else ""}</small></div>'
def composer():return f'<div class="composer">{ib("plus")}<span class="input">Сообщение…</span>{ib("mic","accent")}</div><div class="composerhint">Микрофон — записать голосовое</div>'
def item(i,title,sub,extra=''):return f'<div class="item">{ib(i)}<div><b>{title}</b><small>{sub}</small></div>{extra or icon("arrow")}</div>'
def contact(name,sub,time,unread=''):
 return f'<div class="contact">{av(name[0])}<div><b>{name}</b><small>{sub}</small></div><div class="contactmeta"><small>{time}</small>{f"<em>{unread}</em>" if unread else ""}</div></div>'
def inbox():return f'''<div class="listtop"><div><small>VOICECHAT</small><h3>Разговоры</h3></div>{ib('plus','accent')}</div><div class="search">{icon('search')} Найти разговор</div><div class="segments"><b>Люди</b><span>Группы</span></div><div class="invites">{icon('mail')} Приглашения <b>2</b>{icon('arrow')}</div><div class="eyebrow inphone">НЕДАВНИЕ</div>{contact('Мама','Голосовое · 0:18','14:32','1')}{contact('Аня','Давай созвонимся вечером','13:48')}{contact('Папа','Фото с прогулки','Вчера')}<div class="addperson">{icon('plus')} Найти человека</div><div class="flexspace"></div><div class="bottomnav"><span class="active">{icon('chat')}<small>Разговоры</small></span><span>{icon('search')}<small>Поиск</small></span><span>{icon('settings')}<small>Настройки</small></span></div>'''
def chat():return top('Мама','В сети')+f'<div class="callbar">{icon("phone")} Позвонить <span>Голосовой звонок</span></div><div class="day">Сегодня</div><div class="messages">'+message('В воскресенье собираемся у нас?')+message('Конечно! Буду к пяти.',True,'14:31')+voice()+message('Я приготовлю твой любимый пирог.',time='14:33')+'</div><div class="flexspace"></div><div class="queuebar">'+icon('clock')+' Запланировано · 2 '+icon('arrow')+'</div>'+composer()
def record():return top('Мама','Запись сообщения')+'<div class="day">Сегодня</div>'+message('Расскажи, как прошёл день?')+message('Сейчас запишу голосом.',True,'14:35')+'<div class="flexspace"></div><div class="recordpanel"><div class="recordlabel"><span class="reddot"></span> Идёт запись</div><strong>00:12</strong><small>Осталось 2:48 из 3 минут</small>'+wave()+f'<div class="recordactions"><span>{ib("trash")}<small>Удалить</small></span><span>{ib("stop","accent")}<small>Остановить</small></span></div></div><div class="note centered">После остановки можно прослушать запись и отправить её.</div>'
def toolscreen():return top('Семья','4 участника')+message('В воскресенье в пять?',True,'14:31')+'<div class="flexspace"></div><div class="sheet"><div class="handle"></div><h3>Добавить в сообщение</h3><p>Выберите, чем поделиться</p><div class="toolsgrid">'+''.join(f'<div>{ib(i)}<b>{t}</b></div>' for i,t in [('image','Фото'),('file','Файл'),('video','Видеокружок'),('smile','Эмодзи'),('clock','Отложить'),('clock','Таймер')])+f'</div><div class="sheetfooter">{icon("down")} Закрыть панель</div></div>'+composer()
def call():return top('Семья','Голосовой звонок')+'<div class="calltime">04:32</div><div class="callquality"><span class="bars"><i></i><i></i><i></i><i></i><i></i></span> Хорошая связь</div><div class="callgrid">'+''.join(f'<div class="caller {cl}">{av(a)}<b>{n}</b><small>{s}</small></div>' for a,n,s,cl in [('М','Мама','В звонке',''),('А','Аня','В звонке',''),('В','Вы','В звонке','self'),('П','Папа','Ждём подключения','waiting')])+'</div><div class="flexspace"></div><div class="callcontrols">'+''.join(f'<span>{ib(i)}<small>{t}</small></span>' for i,t in [('mic','Микрофон'),('speaker','Аудиовыход')])+'</div><div class="endcall">'+icon('phone')+' Завершить звонок</div><div class="note centered">Звонок можно свернуть и продолжить переписку.</div>'
def schedule():return top('Запланировано','Семья · 2 сообщения')+hero('ОЧЕРЕДЬ ОТПРАВКИ','В нужный момент.')+'<div class="timezone">'+icon('clock')+' Время вашего устройства</div><div class="schedulecard"><div class="schedtime">Сегодня <b>17:00</b></div><p>Напомню: встречаемся в пять!</p>'+tag('Ожидает публикации')+'<div class="cancel">Отменить отправку</div></div><div class="schedulecard"><div class="schedtime">Завтра <b>09:00</b></div><p>Доброе утро! Хорошего дня.</p>'+tag('Ожидает публикации')+'<div class="cancel">Отменить отправку</div></div><div class="note">После подтверждения сервером приложение можно закрыть.</div><div class="flexspace"></div><div class="outlinebutton">'+icon('refresh')+' Обновить очередь</div>'
def devices():return top('Устройства','Доступ к аккаунту')+hero('БЕЗОПАСНОСТЬ','Знакомые устройства.')+'<div class="devicecard"><div class="devtitle">'+ib('device')+'<div><b>Этот Android</b><small>Текущее устройство</small></div></div>'+tag('Проверено','verified')+'<div class="fingerprint">Идентификатор <b>VC · ANDROID · 01</b></div></div><div class="devicecard"><div class="devtitle">'+ib('device')+'<div><b>Браузер на ноутбуке</b><small>Другой сеанс</small></div></div>'+tag('Требует проверки','pending')+'<div class="solidbutton">Проверить устройство</div></div><div class="note">Сравните коды на обоих устройствах или отсканируйте QR.</div><div class="flexspace"></div><div class="dangerlink">Отозвать доступ устройства</div><div class="note">Отзыв завершит сеанс. Уже сохранённые копии удалить удалённо нельзя.</div>'
def settings():return top('Настройки','Ваше пространство')+'<div class="profilecard">'+av('А')+'<div><b>Антон</b><small>Мой профиль</small></div>'+icon('arrow')+'</div><div class="settingsgroup">'+item('settings','Оформление','Цветовая схема Nocturne')+item('speaker','Звуки','Сообщения и звонки включены')+'</div><div class="eyebrow inphone">УСТРОЙСТВА И ИСТОРИЯ</div><div class="settingsgroup">'+item('device','Устройства','2 сеанса · 1 требует проверки')+item('lock','Доступ к истории','Ключ и восстановление')+item('file','Локальная копия','328 из 1024 МиБ')+'</div><div class="note">Лимит копии не равен свободному месту на диске.</div><div class="flexspace"></div><div class="dangerlink">Выйти из аккаунта</div>'
SCREENS=[('inbox','Разговоры',inbox,'Компактная шапка; приглашения видны; поиск и настройки доступны снизу.'),('chat','Переписка',chat,'Вызов подписан отдельно. Голосовой плеер заметен, очередь находится рядом с вводом.'),('record','Запись голоса',record,'Стоп и удаление разделены. Отправка доступна только после завершения записи.'),('tools','Вложения и инструменты',toolscreen,'Шесть подписанных действий вместо тесного ряда непонятных иконок.'),('call','Групповой звонок',call,'Состав звонка и ожидающие участники видны одновременно. Завершение выделено отдельно.'),('schedule','Отложенные сообщения',schedule,'Время, содержимое и статус в одной карточке; отмена названа явно.'),('devices','Устройства',devices,'Проверенные и новые устройства различаются текстом, а не только цветом.'),('settings','Настройки',settings,'Профиль, оформление и доступ к истории сгруппированы по назначению.')]
