CSS += '\n:root{--ink:#37323c;--muted:#656472}.themebutton .orb{background:var(--tint);border:1px solid var(--accent)}.themebutton[aria-pressed=true]{outline-color:var(--accent)}.phone{border-color:var(--surface)}.iconbox.accent,.bubble.own,.contactmeta em,.invites b,.solidbutton,.profilecard .avatar{background:var(--tint);color:var(--on)}.bubble.own small{color:var(--on)}.solidbutton{border:1px solid color-mix(in srgb,var(--accent) 25%,transparent)}.voice{border:1px solid color-mix(in srgb,var(--accent) 12%,transparent)}.avatar{background:var(--raised)}.caller.self{border-color:var(--accent)}.sheet,.recordpanel{box-shadow:0 8px 24px #25203008}.themebutton{color:var(--ink)}.cover .eyebrow,.cover p,.covermeta{color:#656472}.chapterhead h2{color:var(--accent)}.cover h1 span{color:#66508c}.endcall{color:#ffffff}.desktopwindow{box-shadow:0 15px 35px #302b2510}\n'
# Measure actual opaque text/surface pairs, not an untested 'accessible' badge.
def luminance(h):
 rgb=[int(h[i:i+2],16)/255 for i in [1,3,5]]
 rgb=[c/12.92 if c<=.04045 else ((c+.055)/1.055)**2.4 for c in rgb]
 return sum(c*w for c,w in zip(rgb,[.2126,.7152,.0722]))
def contrast(a,b):
 x,y=sorted([luminance(a),luminance(b)])
 return round((y+.05)/(x+.05),2)
reports=[]
for t in THEMES:
 pairs={'text':contrast(t[11],t[5]),'secondary':contrast(t[8],t[5]),'button':contrast(t[7],t[10]),'accent':contrast(t[6],t[4]),'secondaryAccent':contrast(t[9],t[5])}
 assert min(pairs.values())>=4.5,(t[0],pairs)
 reports.append({'theme':t[1],**pairs})
body='''<header class="cover"><div class="eyebrow">VOICECHAT / NOCTURNE IN DAYLIGHT / VOL. 03 / PASTEL EDITION</div><h1>Мягкий свет.<br><span>Десять оттенков.</span></h1><p>Светлая сторона Nocturne. Та же спокойная компоновка и восемь знакомых экранов — в десяти нежных пастельных палитрах.</p><div class="covermeta"><span>23 ОКТЯБРЯ 2026</span><span>10 ТЕМ × 8 ЭКРАНОВ</span><span>МОБИЛЬНЫЙ + DESKTOP</span></div></header><nav class="toolbar" aria-label="Управление артбуком"><label for="themeSelect">Цветовая схема</label><select id="themeSelect">'''+''.join(f'<option value="{t[0]}">{t[1]}</option>' for t in THEMES)+'''</select><label for="screenSelect">Экран</label><select id="screenSelect"><option value="all">Все восемь экранов</option>'''+''.join(f'<option value="{s[0]}">{s[1]}</option>' for s in SCREENS)+'''</select><a href="#compare" class="push">Сравнить 10 тем</a><a href="#desktop">Desktop</a></nav><section class="chooser"><h2>Цвет меняется. Удобство остаётся.</h2><p>Одинаковые сценарии и компоновка помогают сравнить именно цвет. У каждой темы собственные фон, светлые поверхности, пастельная заливка, глубокий акцент и читаемый вторичный текст. Красный оставлен для завершения звонка и опасных действий.</p><div class="swatchgrid">'''
for t in THEMES:body+=f'<button type="button" class="themebutton" data-theme="{t[0]}" style="{vars(t)}" aria-pressed="{str(t[0]=="cloud").lower()}"><span class="orb"></span><span><b>{t[1]}</b><small>{t[2].split(" · ")[0]}</small></span></button>'
body+='</div></section>'
for t,r in zip(THEMES,reports):
 body+=f'<section class="themechapter" id="theme-{t[0]}" style="{vars(t)}" {"" if t[0]=="cloud" else "hidden"}><div class="chapterhead"><div><div class="eyebrow">NOCTURNE / PASTEL STUDY</div><h2>{t[1]}</h2><p>{t[2]}</p><div class="palette">'+''.join(f'<i style="background:{c}"></i>' for c in [t[3],t[4],t[5],t[10],t[6]])+f'<span>{t[6].upper()} · глубокий акцент</span></div></div><div class="right"><p>Светлая основа, нежные цветные поверхности и глубокие оттенки текста. Пастель остаётся в заливках; значимые подписи и иконки сохраняют контраст.</p><p>Контраст текста на поднятой поверхности: <b>{r["text"]}:1</b>; вторичного текста: <b>{r["secondary"]}:1</b>.</p><span class="selection">Концептуальные экраны на основе функций VoiceChat</span></div></div><div class="gallery">'
 for key,title,fn,desc in SCREENS:body+=phone(key,title,fn(),desc)
 body+='</div><div class="themefooter"><div><b>Что изменилось в UX</b><br>Подписанный звонок; удобная панель вложений; явные состояния записи и очереди; отдельные карточки устройств. В макете пустого ввода показан микрофон, при вводе текста его заменяет отправка.</div><div><b>Общая система Nocturne</b><br>Три уровня светлых поверхностей. Голосовой плеер — самый заметный блок сообщения. Служебный текст не теряется в сером. Новая тема не меняет смысл действий и статусов.</div></div></section>'
body+='<section class="comparison" id="compare"><div class="eyebrow">СРАВНЕНИЕ НА ОДНОМ ЭКРАНЕ</div><h2>Какой оттенок ваш?</h2><p>Одна переписка во всех десяти схемах. Полные экраны каждой темы доступны через переключатель наверху. Это авторские макеты, а не снимки новой сборки приложения.</p><div class="comparegrid">'
for t in THEMES:body+=f'<div class="comparecard" style="{vars(t)}"><h3>{t[1]}</h3>'+phone('chat',t[1],chat())+'</div>'
body+='</div></section><section class="desktopsection" id="desktop" style="'+vars(THEMES[0])+'"><div class="eyebrow">NOCTURNE / АДАПТИВНЫЙ WEB</div><h2>Больше места. Больше контекста.</h2><p>Цвет этой компоновки следует выбранной теме. Список остаётся слева, разговор — по центру, расписание и поиск — в панели по запросу. На телефоне дополнительная панель становится отдельным экраном.</p><div class="desktopwindow"><div class="desktopbar">VoiceChat · <span id="desktopThemeName">Lavender Cloud</span> / desktop reference</div><div class="workspace"><aside class="deskinbox"><h3>Разговоры</h3><div class="search">'+icon('search')+' Поиск</div>'+contact('Мама','Голосовое · 0:18','14:32','1')+contact('Аня','До вечера!','13:48')+contact('Папа','Фотография','Вчера')+'</aside><div class="deskchat">'+chat()+'</div><aside class="deskaside"><h3>В этом разговоре</h3>'+item('clock','Запланировано','2 сообщения')+item('search','Поиск по истории','По загруженным сообщениям')+'<div class="note">Панель открывается по запросу. Возврат в переписку сохраняет место чтения.</div></aside></div></div></section><section class="notes"><div class="eyebrow">ГРАНИЦЫ И ПРОВЕРКА</div><h2>Референсы с опорой на продукт.</h2><details><summary>Функции и честные ограничения</summary><p>Изучены текущие Flutter-компоненты переписки, записи, звонков, расписания и устройств, а также ранее просмотренная галерея Android/web. Эти восемь экранов — новые визуальные предложения на основе существующих функций, с вымышленными контактами и данными.</p><p>Групповой звонок показывает текущих участников и ожидающих подключения; максимум продукта — 10 человек. Макет не утверждает наличие детектора активного говорящего. Запись ограничена 3 минутами; пауза и транскрипция не придуманы. Отмена запланированной отправки соответствует текущему сценарию. При изменении времени сообщения нужен отдельный сценарий, он здесь не показан.</p><p>Демонстрация экрана остаётся экспериментальной и выключенной по умолчанию; не добавлена как обещание готовой функции. QR, входящие звонки, видео, восстановление истории, ошибки сети и вход требуют последующих макетов в выбранной теме. Проверено оформление артбука, не работоспособность медиапотока и не аппаратные сценарии.</p></details><details><summary>Контраст палитр</summary><p>Проверены непрозрачные пары: основной и вторичный текст на цветной поверхности, текст кнопки на пастельной заливке, акцент на поверхности и вторичный акцент на поднятой поверхности. Все эти пары ≥ 4.5:1. Это проверка токенов; она не заменяет аудит всех состояний приложения.</p><table><thead><tr><th>Тема</th><th>Основной</th><th>Вторичный</th><th>Кнопка</th><th>Акцент</th></tr></thead><tbody>'
for r in reports:body+=f'<tr><td>{r["theme"]}</td><td>{r["text"]}:1</td><td>{r["secondary"]}:1</td><td>{r["button"]}:1</td><td>{r["accent"]}:1</td></tr>'
body+='</tbody></table></details><details><summary>Принципы ui-ux-pro-max и следующий этап</summary><p>Приоритеты: контраст и иерархия, разделение записи и звонка, видимые подписи, группировка действий, постоянная доступность основных контролов. При переносе в Flutter: цели касания минимум 48 dp на Android, расширение области маленьких иконок, масштабирование текста, клавиатура, безопасные отступы, screen reader и reduced motion. Макеты уменьшены для сравнения; они не являются спецификацией hit area.</p><p>На этапе реализации нужно проверить длинные имена и сообщения, 10 участников звонка, потерю связи, загрузку, ошибки, пустые списки и доступность на реальных устройствах. Состояния доверия и качества в артбуке иллюстративные.</p></details><p><a href="../artbook-2026-10/index.html#nocturne">Исходный Nocturne в первом артбуке</a> · <a href="../nocturne-colors/index.html">Десять тёмных тем</a></p></section>'
body+='<script>const THEMES='+json.dumps([{'id':t[0],'name':t[1],'style':vars(t)} for t in THEMES],ensure_ascii=False)+''';const themeSelect=document.querySelector('#themeSelect'),screenSelect=document.querySelector('#screenSelect');function update(scroll=false){const theme=THEMES.find(t=>t.id===themeSelect.value);document.querySelectorAll('.themechapter').forEach(el=>{el.hidden=el.id!=='theme-'+theme.id;el.querySelectorAll('.screenfigure').forEach(f=>f.hidden=screenSelect.value!=='all'&&f.dataset.screen!==screenSelect.value)});document.querySelectorAll('.themebutton').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.theme===theme.id)));document.querySelector('#desktop').style.cssText=theme.style;document.querySelector('#desktopThemeName').textContent=theme.name;history.replaceState(null,'','#'+theme.id);if(scroll)document.querySelector('#theme-'+theme.id).scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}themeSelect.onchange=()=>update(true);screenSelect.onchange=()=>update(true);document.querySelectorAll('.themebutton').forEach(b=>b.onclick=()=>{themeSelect.value=b.dataset.theme;update(true)});if(THEMES.some(t=>t.id===location.hash.slice(1))){themeSelect.value=location.hash.slice(1);update(false)}</script>'''
